(function(){document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("[data-file-upload]").forEach(o=>{const n=o.querySelector(".lead-form__file-input"),t=o.querySelector("[data-file-preview]");if(!n||!t)return;const r=()=>{const{files:e}=n;if(!e||e.length===0){t.textContent="Inga filer valda";return}if(e.length===1){t.textContent=e[0].name;return}t.textContent=e.length+" filer valda"};n.addEventListener("change",r)})})})();
